#define MAXN 50005
#define MAXM 200005

typedef struct {
    int to;
    int next;
} Edge;

Edge edges[MAXM * 2];
int head[MAXN];
int edge_cnt;

int dist_s[MAXN], dist_t[MAXN];
int n, m, s, t;

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

void bfs(int start, int dist[]) {
    int queue[MAXN];
    int front = 0, rear = 0;
    for (int i = 0; i < n; i++) dist[i] = -1;
    dist[start] = 0;
    queue[rear++] = start;
    while (front < rear) {
        int u = queue[front++];
        for (int i = head[u]; i != -1; i = edges[i].next) {
            int v = edges[i].to;
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                queue[rear++] = v;
            }
        }
    }
}

