    s--; t--;

    int *head = (int *)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) head[i] = -1;

    Edge *edges = (Edge *)malloc((2LL * m) * sizeof(Edge));
    char *adj = (char *)calloc((ll)n * n, sizeof(char));

    int ecnt = 0;
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        edges[ecnt].to = v;
        edges[ecnt].next = head[u];
        head[u] = ecnt++;
        edges[ecnt].to = u;
        edges[ecnt].next = head[v];
        head[v] = ecnt++;
        adj[(ll)u * n + v] = 1;
        adj[(ll)v * n + u] = 1;
    }

    int *distS = (int *)malloc(n * sizeof(int));
    int *distT = (int *)malloc(n * sizeof(int));
    int *queue = (int *)malloc(n * sizeof(int));

    for (int i = 0; i < n; i++) distS[i] = distT[i] = -1;

    int qh = 0, qt = 0;
    queue[qt++] = s;
    distS[s] = 0;
    while (qh < qt) {
        int v = queue[qh++];
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (distS[to] == -1) {
                distS[to] = distS[v] + 1;
                queue[qt++] = to;
            }
        }
    }

    qh = qt = 0;
    queue[qt++] = t;
    distT[t] = 0;
    while (qh < qt) {
        int v = queue[qh++];
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (distT[to] == -1) {
                distT[to] = distT[v] + 1;
                queue[qt++] = to;
            }
        }
    }

    int D = distS[t];
    ll ans = 0;

    for (int u = 0; u < n; u++) {
        for (int v = u + 1; v < n; v++) {
            if (adj[(ll)u * n + v]) continue;

            int ok = 0;
            if (distS[u] != -1 && distT[v] != -1 && distS[u] + 1 + distT[v] == D - 1) ok = 1;
            if (distS[v] != -1 && distT[u] != -1 && distS[v] + 1 + distT[u] == D - 1) ok = 1;

            if (ok) ans++;
        }
    }

    printf("%lld\n", ans);

    free(head);
    free(edges);
    free(adj);
    free(distS);
    free(distT);
    free(queue);
    return 0;
}

