    cin >> N >> M >> s >> t;
    --s; --t;

    vector<vector<int>> g(N);
    vector<vector<bool>> adj(N, vector<bool>(N, false));

    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        g[u].push_back(v);
        g[v].push_back(u);
        adj[u][v] = adj[v][u] = true;
    }

    auto bfs = [&](int src) {
        const int INF = 1e9;
        vector<int> dist(N, INF);
        queue<int> q;
        dist[src] = 0;
        q.push(src);
        while (!q.empty()) {
            int v = q.front();
            q.pop();
            for (int to : g[v]) {
                if (dist[to] > dist[v] + 1) {
                    dist[to] = dist[v] + 1;
                    q.push(to);
                }
            }
        }
        return dist;
    };

    vector<int> ds = bfs(s);
    vector<int> dt = bfs(t);

    int D = ds[t];
    long long ans = 0;

    for (int u = 0; u < N; ++u) {
        for (int v = u + 1; v < N; ++v) {
            if (adj[u][v]) continue;

            int best = D;
            if (ds[u] < (int)1e9 && dt[v] < (int)1e9)
                best = min(best, ds[u] + 1 + dt[v]);
            if (ds[v] < (int)1e9 && dt[u] < (int)1e9)
                best = min(best, ds[v] + 1 + dt[u]);

            if (best == D - 1) ++ans;
        }
    }

    cout << ans << '\n';
    return 0;
}

import java.io.*;
