public class Main {
    static final int INF = Integer.MAX_VALUE / 2;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        int s = Integer.parseInt(firstLine[2]) - 1;
        int t = Integer.parseInt(firstLine[3]) - 1;

        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int i = 0; i < m; i++) {
            String[] edge = br.readLine().split(" ");
            int u = Integer.parseInt(edge[0]) - 1;
            int v = Integer.parseInt(edge[1]) - 1;
            graph.get(u).add(new int[]{v, 1});
            graph.get(v).add(new int[]{u, 1});
        }

        int[] distS = dijkstra(graph, s, n);
        int[] distT = dijkstra(graph, t, n);

        int shortest = distS[t];

        int beauty = 0;
        // Try all possible edges between distinct vertices
        for (int u = 0; u < n; u++) {
            for (int v = u + 1; v < n; v++) {
                // If edge already exists, skip
                boolean exists = false;
                for (int[] neighbor : graph.get(u)) {
                    if (neighbor[0] == v) {
                        exists = true;
                        break;
                    }
                }
                if (exists) continue;

                // New shortest path after adding edge (u,v)
                int newDist = Math.min(distS[u] + 1 + distT[v], distS[v] + 1 + distT[u]);
                if (newDist == shortest + 1) {
                    beauty++;
                }
            }
        }

        System.out.println(beauty);
    }

    static int[] dijkstra(List<List<int[]>> graph, int start, int n) {
        int[] dist = new int[n];
        Arrays.fill(dist, INF);
        dist[start] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[1]));
        pq.offer(new int[]{start, 0});

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int node = cur[0];
            int d = cur[1];
            if (d > dist[node]) continue;
            for (int[] neighbor : graph.get(node)) {
                int next = neighbor[0];
                int nd = d + neighbor[1];
                if (nd < dist[next]) {
                    dist[next] = nd;
                    pq.offer(new int[]{next, nd});
                }
            }
        }
        return dist;
    }
}

