public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        Set<Long> edges = new HashSet<>();
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt(), v = sc.nextInt();
            adj.get(u).add(v);
            adj.get(v).add(u);
            long key = Math.min(u,v) * 10000L + Math.max(u,v);
            edges.add(key);
        }
        int s = sc.nextInt(), t = sc.nextInt();
        int[] ds = bfs(s, n, adj);
        int[] dt = bfs(t, n, adj);
        int dst = ds[t];
        if (dst < 0) { System.out.println(0); return; }
        long count = 0;
        int target = dst - 2;
        for (int u = 1; u <= n; u++) {
            if (ds[u] < 0) continue;
            for (int v = u+1; v <= n; v++) {
                if (dt[v] < 0 && dt[u] < 0) continue;
                long key = (long)u * 10000L + v;
                if (edges.contains(key)) continue;
                int val = Math.min(
                    ds[u] == Integer.MAX_VALUE/2 || dt[v] == Integer.MAX_VALUE/2 ? Integer.MAX_VALUE/2 : ds[u] + dt[v],
                    ds[v] == Integer.MAX_VALUE/2 || dt[u] == Integer.MAX_VALUE/2 ? Integer.MAX_VALUE/2 : ds[v] + dt[u]
                );
                if (val == target) count++;
            }
        }
        System.out.println(count);
    }
    static int[] bfs(int src, int n, List<List<Integer>> adj) {
        int[] d = new int[n+1]; Arrays.fill(d, -1); d[src] = 0;
        Queue<Integer> q = new LinkedList<>(); q.add(src);
        while (!q.isEmpty()) { int u = q.poll(); for (int v : adj.get(u)) if (d[v]==-1) { d[v]=d[u]+1; q.add(v); } }
        return d;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        int m = fs.nextInt();
        int s = fs.nextInt() - 1;
        int t = fs.nextInt() - 1;

        ArrayList<Integer>[] g = new ArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

        boolean[][] hasEdge = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            g[u].add(v);
            g[v].add(u);
            hasEdge[u][v] = true;
            hasEdge[v][u] = true;
        }

        int[] ds = bfs(g, s);
        int[] dt = bfs(g, t);

        int D = ds[t];
        long ans = 0;

        for (int u = 0; u < n; u++) {
            for (int v = u + 1; v < n; v++) {
                if (hasEdge[u][v]) continue;

                int best = D;

                if (ds[u] != -1 && dt[v] != -1) {
                    best = Math.min(best, ds[u] + 1 + dt[v]);
                }
                if (ds[v] != -1 && dt[u] != -1) {
                    best = Math.min(best, ds[v] + 1 + dt[u]);
                }

                if (best == D - 1) ans++;
            }
        }

        System.out.println(ans);
    }

    static int[] bfs(ArrayList<Integer>[] g, int src) {
        int n = g.length;
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        dist[src] = 0;
        q.add(src);

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                }
            }
        }
        return dist;
    }
}
